import{_ as e,o as r,c as l,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const p=JSON.parse('{"title":"Ceph Orchestrator 2022-12-06","description":"","frontmatter":{"title":"Ceph Orchestrator 2022-12-06","date":"2022-12-06T00:00:00.000Z","updated":"2022-12-06T00:00:00.000Z","tags":["Ceph","Distributed Storage","OpenStack","NFS","Regression"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2022/Ceph_Orchestrator_2022-12-06.md","filePath":"posts/2022/Ceph_Orchestrator_2022-12-06.md","lastUpdated":1780459816000}'),i={name:"posts/2022/Ceph_Orchestrator_2022-12-06.md"};function o(s,a,n,h,c,d){return r(),l("div",null,[...a[0]||(a[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议时间-具体日期" tabindex="-1">会议时间：[具体日期] <a class="header-anchor" href="#会议时间-具体日期" aria-label="Permalink to &quot;会议时间：[具体日期]&quot;">​</a></h4><h4 id="参会人员-具体人员名单" tabindex="-1">参会人员：[具体人员名单] <a class="header-anchor" href="#参会人员-具体人员名单" aria-label="Permalink to &quot;参会人员：[具体人员名单]&quot;">​</a></h4><h4 id="主要议题" tabindex="-1">主要议题： <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题：&quot;">​</a></h4><ol><li><strong>OpenStack Tracker 更新</strong></li><li><strong>NFS 相关问题讨论</strong></li></ol><h4 id="讨论内容" tabindex="-1">讨论内容： <a class="header-anchor" href="#讨论内容" aria-label="Permalink to &quot;讨论内容：&quot;">​</a></h4><h5 id="_1-openstack-tracker-更新" tabindex="-1">1. OpenStack Tracker 更新 <a class="header-anchor" href="#_1-openstack-tracker-更新" aria-label="Permalink to &quot;1. OpenStack Tracker 更新&quot;">​</a></h5><ul><li><strong>背景</strong>：讨论了在Ceph中定制每个OSD的crash设备类的问题。SafeTangible使用批处理模式，通过传递OSD列表来准备和激活设备。</li><li><strong>当前问题</strong>：CI环境中为SSD创建crash层次结构并应用规则时，由于缺乏对不同crash设备类的支持，无法完全复制过去的功能。</li><li><strong>解决方案</strong>： <ul><li>创建了一个新的tracker来比较过去和现在的实现。</li><li>讨论了是否引入不同的语法为设备类，或优化现有路径处理以支持每个OSD的设备类。</li><li>建议使用字典格式在spec中定义设备类，并优化批处理模式以减少OSD部署时间。</li><li>决定通过分组设备类来优化set volume命令的执行，最多可能需要三个批处理命令。</li></ul></li></ul><h5 id="_2-nfs-相关问题讨论" tabindex="-1">2. NFS 相关问题讨论 <a class="header-anchor" href="#_2-nfs-相关问题讨论" aria-label="Permalink to &quot;2. NFS 相关问题讨论&quot;">​</a></h5><ul><li><strong>背景</strong>：会议中提到了NFS相关的调试问题，特别是关于一个可能导致回归的新配置部分。</li><li><strong>当前问题</strong>：RC Frank可能引入了一个回归问题，导致无法在IRC中发送消息。</li><li><strong>解决方案</strong>： <ul><li>尝试通过修改配置来解决问题。</li><li>计划在会议后进行进一步的调试和实验。</li><li>讨论了如何处理旧版本的兼容性问题。</li></ul></li></ul><h4 id="决定事项" tabindex="-1">决定事项： <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项：&quot;">​</a></h4><ul><li>对于OpenStack Tracker问题，决定使用字典格式在spec中定义设备类，并通过分组优化set volume命令的执行。</li><li>对于NFS问题，计划在会议后进行进一步的调试和实验，并考虑旧版本的兼容性问题。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ul><li>更新tracker，记录会议中的讨论和决定。</li><li>进行NFS相关的调试和实验，以确定问题的根本原因并寻找解决方案。</li><li>考虑旧版本的兼容性问题，并与相关团队合作解决。</li><li>讨论团队过渡问题，以及如何更好地支持新成员和处理项目中的问题。</li><li>更新测试套件，处理剩余的小问题。</li></ul><h4 id="其他事项" tabindex="-1">其他事项： <a class="header-anchor" href="#其他事项" aria-label="Permalink to &quot;其他事项：&quot;">​</a></h4><ul><li>会议中还讨论了团队的过渡问题，以及如何更好地支持新成员和处理项目中的问题。</li><li>提到了测试套件的更新和优化，以及如何处理剩余的小问题。</li></ul><h4 id="会议结束" tabindex="-1">会议结束： <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束：&quot;">​</a></h4><ul><li>会议在讨论了所有议题后结束，计划下周再次开会。</li></ul><h4 id="备注" tabindex="-1">备注： <a class="header-anchor" href="#备注" aria-label="Permalink to &quot;备注：&quot;">​</a></h4><ul><li>会议中提到的具体技术细节和代码修改将在后续的开发和调试中进一步明确和实施。</li></ul><p>以上是本次会议的纪要，涵盖了会议的关键细节、讨论的主要议题、决定的事项以及后续的行动计划。</p>',21)])])}const _=e(i,[["render",o]]);export{p as __pageData,_ as default};
